files.content:
@keyframes enter { from { opacity: 0; transform: translateY(24px) scale(.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes float { to { transform: translateY(-12px); } }
.modal { animation: enter 200ms ease-out; }
.decoration { animation: float 2s ease-in-out infinite alternate; }
